  gap: 30px;
}

.product-card {
  group: hover;
  transition: var(--transition);
}

.product-image {
  background: var(--gray-100);
  aspect-ratio: 1/1;
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 15px;
  position: relative;
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: var(--transition);
}

.product-card:hover .product-image img {
  transform: scale(1.05);
}

.product-info h3 {
  font-size: 1.1rem;
  margin-bottom: 5px;
}

.product-price {
  font-weight: 600;
}

.deal-tag {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #e30000;
  color: white;
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 700;
}

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.editorial-content h2 {
  font-size: 2.5rem;
  margin-bottom: 20px;
}

.editorial-image {
  border-radius: 20px;
  overflow: hidden;
}

/* Footer */
footer {
  padding: 60px 0;
  border-top: 1px solid var(--gray-200);
  background: var(--gray-100);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
}

.footer-col h4 {
  margin-bottom: 20px;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--gray-600);
  font-size: 0.9rem;
}

.footer-col a:hover {
  color: var(--primary);
}

@media (max-width: 768px) {
  .hero-content h1 {
    font-size: 2.5rem;
  }
  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}
